'use client';
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';
import { spring, springToLinear, useInView, useStudioMotion } from '../../../motion';
import { resolveParams, type EffectMeta, type ParamValues } from '../../../types';
import VariableWeightWave from '../../../effects/variable-weight-wave';
import { meta as waveMeta } from '../../../effects/variable-weight-wave/meta';
import ScrambleDecode from '../../../effects/scramble-decode';
import { meta as scrambleMeta } from '../../../effects/scramble-decode/meta';
import SplitLineReveal from '../../../effects/split-line-reveal';
import { meta as splitMeta } from '../../../effects/split-line-reveal/meta';
import KineticMarquee from '../../../effects/kinetic-marquee';
import { meta as marqueeMeta } from '../../../effects/kinetic-marquee/meta';
import { AREAS, Coastline } from './Coastline';
import { Dial } from './Dial';
import { ForceScale, Winds } from './Winds';
import s from './styles.module.css';

if (typeof window !== 'undefined') gsap.registerPlugin(ScrollTrigger, useGSAP);

/** Every recipe param from its meta (defaults), then this demo's overrides. */
const recipe = <T,>(m: EffectMeta, overrides: ParamValues = {}): T => resolveParams(m.params, overrides) as unknown as T;

/** Default lamp: upper left. Shadows (--kt-sx/--kt-sy, −1…1) fall away from it. */
const LAMP = { x: 0.22, y: 0.12 };

/** Mounts a time-based recipe only once it is well inside the viewport, so its entrance is actually seen. */
function OnView({ children, placeholder, className }: { children: ReactNode; placeholder: ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref, { amount: 0.45 });
  const { reduced } = useStudioMotion();
  return <div ref={ref} className={className}>{near || reduced ? children : placeholder}</div>;
}

function Cue({ time, children, className, labelledBy }: { time: string; children: ReactNode; className?: string; labelledBy?: string }) {
  return (
    <section className={`${s.cue} ${className ?? ''}`} aria-labelledby={labelledBy}>
      <p className={s.time} aria-hidden="true">{time}</p>
      <div className={s.cueBody}>{children}</div>
    </section>
  );
}

export default function KineticTypography() {
  const { reduced } = useStudioMotion();
  const [paused, setPaused] = useState(false);
  const moving = !reduced && !paused;
  const root = useRef<HTMLDivElement>(null);
  const hero = useRef<HTMLElement>(null);
  const lamp = useRef<HTMLDivElement>(null);
  const marquee = useRef<HTMLDivElement>(null);
  const press = useState(() => springToLinear(spring.press))[0];

  // Trigger refreshes for the wind list: every trigger on the page depends on fonts and on the frame width.
  useGSAP(() => {
    const el = root.current;
    if (reduced || !el) return;
    let width = el.clientWidth;
    let timer = 0;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      window.clearTimeout(timer);
      timer = window.setTimeout(() => ScrollTrigger.refresh(), 140);
    });
    ro.observe(el);
    let alive = true;
    void document.fonts?.ready.then(() => { if (alive) ScrollTrigger.refresh(); });
    return () => { alive = false; ro.disconnect(); window.clearTimeout(timer); };
  }, { scope: root, dependencies: [reduced], revertOnUpdate: true });

  // The pointer is a desk lamp: a warm pool follows it and the display type's shadows swing away from it. Damped,
  // one rAF loop that sleeps once settled; mouse and pen only (on touch the lamp stays upper left).
  useEffect(() => {
    const el = root.current;
    const pool = lamp.current;
    if (!el || !pool || reduced) return;
    const st = { tx: -1, ty: -1, x: -1, y: -1, cx: -1, cy: -1, raf: 0, last: 0, key: '' };
    const place = () => {
      const r = pool.getBoundingClientRect();
      if (st.cx < 0) return;
      st.tx = st.cx - r.left;
      st.ty = st.cy - r.top;
      if (st.x < 0) { st.x = st.tx; st.y = st.ty; }
    };
    const tick = (now: number) => {
      st.raf = 0;
      const dt = Math.min(0.05, st.last ? (now - st.last) / 1000 : 0.016);
      st.last = now;
      const k = 1 - Math.exp(-dt * 7);
      st.x += (st.tx - st.x) * k;
      st.y += (st.ty - st.y) * k;
      const w = Math.max(1, pool.clientWidth);
      const h = Math.max(1, pool.clientHeight);
      const sx = Math.max(-1, Math.min(1, (0.5 - st.x / w) * 2));
      const sy = Math.max(-1, Math.min(1, (0.5 - st.y / h) * 2));
      const key = `${st.x.toFixed(1)} ${st.y.toFixed(1)}`;
      if (key !== st.key) {
        st.key = key;
        pool.style.setProperty('--kt-lamp-x', `${st.x.toFixed(1)}px`);
        pool.style.setProperty('--kt-lamp-y', `${st.y.toFixed(1)}px`);
        el.style.setProperty('--kt-sx', sx.toFixed(3));
        el.style.setProperty('--kt-sy', sy.toFixed(3));
      }
      if (Math.abs(st.tx - st.x) + Math.abs(st.ty - st.y) > 0.3) st.raf = requestAnimationFrame(tick);
      else st.last = 0;
    };
    const wake = () => { if (!st.raf) st.raf = requestAnimationFrame(tick); };
    const onMove = (e: PointerEvent) => {
      if (e.pointerType !== 'mouse' && e.pointerType !== 'pen') return;
      st.cx = e.clientX;
      st.cy = e.clientY;
      place();
      wake();
    };
    const onScroll = () => { place(); wake(); };
    el.addEventListener('pointermove', onMove, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      el.removeEventListener('pointermove', onMove);
      window.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(st.raf);
      ['--kt-sx', '--kt-sy'].forEach((p) => el.style.removeProperty(p));
      ['--kt-lamp-x', '--kt-lamp-y'].forEach((p) => pool.style.removeProperty(p));
    };
  }, [reduced]);

  // One pause control for the whole piece: the marquee recipe keeps its own button, so mirror the state onto it.
  useEffect(() => {
    const btn = marquee.current?.querySelector<HTMLButtonElement>('button[aria-pressed]');
    if (btn && (btn.getAttribute('aria-pressed') === 'true') !== paused) btn.click();
  }, [paused, reduced]);

  return (
    <div
      ref={root}
      className={s.root}
      data-paused={paused || undefined}
      style={{ '--kt-sx': (0.5 - LAMP.x) * 2, '--kt-sy': (0.5 - LAMP.y) * 2, '--kt-press': press.easing, '--kt-press-dur': `${press.duration}ms` } as CSSProperties}
    >
      <div ref={lamp} className={s.lampPool} aria-hidden="true" />
      <div className={s.bar}>
        <p className={s.station}>
          <span className={s.lamp} aria-hidden="true" />
          <span className={s.stationName}>Radio Haar</span>
          <span>97.4 FM</span>
          <span className={s.fict}>fictional station</span>
        </p>
        {reduced ? (
          <p className={s.barNote}>Reduced motion: all type is still</p>
        ) : (
          <button type="button" className={s.pause} aria-pressed={paused} onClick={() => setPaused((p) => !p)}>
            <svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true" focusable="false">
              {paused ? <path d="M3 1.5v9l7.5-4.5z" fill="currentColor" /> : <path d="M2.5 1.5h2.5v9H2.5zM7 1.5h2.5v9H7z" fill="currentColor" />}
            </svg>
            Pause motion
          </button>
        )}
      </div>

      <section ref={hero} className={`${s.cue} ${s.hero}`}>
        <p className={s.time} aria-hidden="true">00:48:00</p>
        <div className={s.cueBody}>
          <p className={s.kicker}>Inner waters <span aria-hidden="true">·</span> read at 00:48 and 05:20 <span aria-hidden="true">·</span> sample content</p>
          <div className={s.wave}>
            <VariableWeightWave params={recipe(waveMeta, { text: 'The night forecast', minWeight: 250, maxWeight: 800, radius: 1.2, squeeze: true, idle: !paused })} />
          </div>
          <p className={s.voice}>Read slowly, for the boats that are still out.</p>
          <Dial host={hero} reduced={reduced} paused={paused} />
          <p className={s.dialHint} aria-hidden="true">{reduced ? 'Tuned to 97.4' : 'Drag the needle to tune · arrow keys on the dial'}</p>
        </div>
      </section>

      <Cue time="00:48:06" className={s.tune} labelledBy="kt-tune">
        <h2 id="kt-tune" className={s.label}>Tuning in</h2>
        <OnView className={s.decode} placeholder={<p className={s.decodeHold}>Ossel coastguard, 00:48. The forecast for the inner waters for the next 24 hours.</p>}>
          <ScrambleDecode params={recipe(scrambleMeta, { text: 'Ossel coastguard, 00:48. The forecast for the inner waters for the next 24 hours.', duration: 1500, churn: 48, glyphs: 'alphanumeric', seed: 31 })} />
        </OnView>
      </Cue>

      <Cue time="00:48:21" labelledBy="kt-areas">
        <h2 id="kt-areas" className={s.label}>Sea areas, in the order they are read</h2>
        <div className={s.chartFrame}><Coastline moving={moving} /></div>
        <p className={s.areaList}>{AREAS.join(' · ')}</p>
      </Cue>

      <Cue time="00:48:40" labelledBy="kt-wind">
        <h2 id="kt-wind" className={s.label}>Wind</h2>
        <Winds reduced={reduced} />
        <ForceScale />
      </Cue>

      <Cue time="00:49:32" className={s.state}>
        <p className={s.label}>Sea state and visibility</p>
        <OnView placeholder={<h2 className={s.stateHold}>Rough, occasionally very rough. Visibility good, becoming poor in haar.</h2>}>
          <SplitLineReveal params={recipe(splitMeta, { text: 'Rough, occasionally very rough. Visibility good, becoming poor in haar.', stagger: 52, duration: 760, rise: 115, skew: true })} />
        </OnView>
      </Cue>

      <Cue time="00:49:50" className={s.gale} labelledBy="kt-gale">
        <h2 id="kt-gale" className={s.label}>Gale warnings in force</h2>
        <div ref={marquee} className={s.marquee}>
          <KineticMarquee params={recipe(marqueeMeta, { text: 'Tarrow Deep / The Dray / Low Marra / Fennick, later', speed: 64, reactivity: 1.1, skew: 8, direction: 'left', pauseOnHover: true, label: '' })} />
        </div>
      </Cue>

      <Cue time="00:50:14" className={s.end} labelledBy="kt-end">
        <h2 id="kt-end" className={s.endLine}>That was the forecast.</h2>
        <p className={s.next}>The next one is read at 05:20, after the news.</p>
        <p className={s.fine}>Radio Haar, its coast and its sea areas are fictional; every wind, sea state and time on this page is sample content, not a forecast.</p>
      </Cue>
    </div>
  );
}

'use client';
import { useEffect, useId, useRef } from 'react';
import { useRafLoop } from '../../../motion';
import s from './styles.module.css';

export const AREAS = ['Skerrow', 'Brannock', 'Hollin Bank', 'Tarrow Deep', 'The Dray', 'Fennick', 'Low Marra', 'Ossel'] as const;

const COAST = 'M-20 120C80 110 120 190 200 170S300 90 380 140S470 250 560 220S660 150 720 210S800 330 900 300S1010 240 1060 320S1150 420 1220 400';
const TEXT_LINE = 'M-20 196C90 186 130 256 210 241S310 171 390 211S480 316 570 291S670 226 730 281S810 396 910 371S1020 311 1070 391S1160 486 1220 471';
const DEPTH_A = 'M-20 286C120 276 200 330 300 316S470 300 560 356S760 420 900 430S1100 470 1220 540';
const DEPTH_B = 'M-20 392C160 380 260 420 380 420S560 440 680 480S900 540 1000 580';
const SOUNDINGS: readonly [number, number, string][] = [
  [80, 330, '14'], [250, 370, '22'], [420, 352, '19'], [620, 420, '31'], [760, 470, '38'], [960, 500, '44'],
  [520, 470, '27'], [330, 470, '25'], [140, 480, '18'], [1110, 520, '47'], [880, 410, '29'], [690, 330, '16'],
];
const TEXT = AREAS.join('  ·  ');
const LAND = `${COAST}L1220 -20L-20 -20Z`;

/** Sea-area names set along the coast on an SVG textPath. They drift like a slow ticker (pausable) and borrow speed from scrolling. */
export function Coastline({ moving }: { moving: boolean }) {
  const ids = useId();
  const pathId = `${ids}-coast-text`;
  const root = useRef<SVGSVGElement>(null);
  const textEl = useRef<SVGTextElement>(null);
  const tp = useRef<SVGTextPathElement>(null);
  const sim = useRef({ x: 0, copy: 0, impulse: 0, boost: 0, lastY: 0 });

  // One copy's length (the text holds two copies so the loop is seamless); re-measured once fonts arrive.
  useEffect(() => {
    let alive = true;
    const measure = () => { if (alive && textEl.current) sim.current.copy = textEl.current.getComputedTextLength() / 2; };
    measure();
    void document.fonts?.ready.then(measure);
    return () => { alive = false; };
  }, [moving]);

  useEffect(() => {
    if (!moving) return;
    sim.current.lastY = window.scrollY;
    const onScroll = () => { const y = window.scrollY; sim.current.impulse += y - sim.current.lastY; sim.current.lastY = y; };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [moving]);

  useRafLoop(root, (dt) => {
    const m = sim.current;
    if (dt <= 0 || !m.copy || !tp.current) return;
    const v = Math.max(-900, Math.min(900, (m.impulse / dt) * 0.6));
    m.impulse = 0;
    m.boost += (v - m.boost) * (1 - Math.exp(-dt * (Math.abs(v) > Math.abs(m.boost) ? 8 : 2.5)));
    m.x = (((m.x + (32 + Math.abs(m.boost)) * dt) % m.copy) + m.copy) % m.copy;
    tp.current.setAttribute('startOffset', (-m.x).toFixed(1));
  }, moving);

  useEffect(() => { if (!moving) { sim.current.x = 0; tp.current?.setAttribute('startOffset', '0'); } }, [moving]);

  return (
    <svg ref={root} className={s.chart} viewBox="0 0 1200 560" role="img" aria-labelledby={`${ids}-t ${ids}-d`} focusable="false" data-moving={moving || undefined}>
      <title id={`${ids}-t`}>Chart of the inner waters (fictional)</title>
      <desc id={`${ids}-d`}>The sea areas are read in order along the coast: {AREAS.join(', ')}.</desc>
      <defs>
        <path id={pathId} d={TEXT_LINE} />
        <clipPath id={`${ids}-land`}><path d={LAND} /></clipPath>
      </defs>
      <path className={s.land} d={LAND} />
      <g className={s.hatch} clipPath={`url(#${ids}-land)`}>
        {Array.from({ length: 22 }, (_, i) => <path key={i} d={`M${i * 64} -20l-460 480`} />)}
      </g>
      <path className={s.coast} d={COAST} />
      <path className={s.depth} d={DEPTH_A} />
      <path className={s.depth} d={DEPTH_B} />
      {SOUNDINGS.map(([x, y, n]) => <text key={`${x}-${y}`} className={s.sounding} x={x} y={y}>{n}</text>)}
      <g className={s.rose} transform="translate(1090 150)">
        <circle r="34" />
        <path d="M0 -48V48M-48 0H48M-24 -24L24 24M24 -24L-24 24" />
        <path className={s.roseN} d="M0 -46L7 -8H-7Z" />
        <text x="-5" y="-54">N</text>
      </g>
      <text ref={textEl} className={s.areaText}>
        <textPath ref={tp} href={`#${pathId}`} startOffset="0">{moving ? `${TEXT}  ·  ${TEXT}  ·  ` : TEXT}</textPath>
      </text>
    </svg>
  );
}

'use client';
import { useEffect, useRef, type KeyboardEvent, type PointerEvent as ReactPointerEvent, type RefObject } from 'react';
import { spring, stepSpring, useRafLoop, type SpringConfig } from '../../../motion';
import s from './styles.module.css';

export const DIAL = { min: 87.5, max: 108, from: 89.1, station: 97.4 };
const fx = (f: number): number => ((f - DIAL.min) / (DIAL.max - DIAL.min)) * 1000;
const TICKS = Array.from({ length: 42 }, (_, i) => DIAL.min + i * 0.5);
/** How clearly the station comes through: 1 on 97.4, gone about half a megahertz either side. */
export const signalAt = (f: number): number => Math.exp(-(((f - DIAL.station) / 0.34) ** 2));
const clampF = (f: number): number => Math.min(DIAL.max, Math.max(DIAL.min, f));

type Mode = 'rest' | 'drag' | 'glide' | 'seek';

/**
 * The tuning dial as an instrument you can handle. Drag the needle (or anywhere on the scale) and it follows with a
 * little weight; let go and it keeps the throw's velocity, slows with friction and is caught by a detent when it passes
 * the station slowly enough. The needle is a real slider: arrows step 0.1 MHz, Page Up/Down 1 MHz, Home/End the ends.
 * It writes --kt-noise (1 − signal) on `host`, so the presenter's line blurs and jitters off-station.
 */
export function Dial({ host, reduced, paused }: { host: RefObject<HTMLElement | null>; reduced: boolean; paused: boolean }) {
  const wrap = useRef<HTMLDivElement>(null);
  const needle = useRef<SVGGElement>(null);
  const shadow = useRef<SVGGElement>(null);
  const handle = useRef<HTMLDivElement>(null);
  const readout = useRef<SVGTextElement>(null);
  const m = useRef({
    // Entrance: the radio tunes itself in — a throw from 89.1 that friction slows and the detent catches on 97.4.
    f: reduced ? DIAL.station : DIAL.from, v: reduced ? 0 : 18.5, mode: (reduced ? 'rest' : 'glide') as Mode, target: DIAL.station, cfg: spring.press as SpringConfig,
    delay: reduced ? 0 : 0.45, id: -1, grab: 0, samples: [] as { t: number; f: number }[], jitT: 0, shown: '', bars: -1, noise: -1,
  });

  const paint = () => {
    const st = m.current;
    const x = fx(st.f).toFixed(1);
    needle.current?.setAttribute('transform', `translate(${x} 0)`);
    shadow.current?.setAttribute('transform', `translate(${x} 0)`);
    const shown = st.f.toFixed(1);
    const sig = signalAt(st.f);
    if (shown !== st.shown) {
      st.shown = shown;
      if (readout.current) readout.current.textContent = shown;
      const h = handle.current;
      if (h) {
        h.style.left = `${((fx(st.f) + 12) / 1024) * 100}%`;
        h.setAttribute('aria-valuenow', shown);
        h.setAttribute('aria-valuetext', `${shown} FM, ${sig > 0.85 ? 'Radio Haar, clear' : sig > 0.25 ? 'Radio Haar, faint' : 'static'}`);
      }
    }
    const bars = Math.round(sig * 5);
    if (bars !== st.bars) { st.bars = bars; wrap.current?.setAttribute('data-bars', String(bars)); }
    const noise = 1 - sig;
    if (Math.abs(noise - st.noise) > 0.01 || (noise < 0.01 && st.noise !== 0)) {
      st.noise = noise < 0.01 ? 0 : noise;
      host.current?.style.setProperty('--kt-noise', st.noise.toFixed(3));
      host.current?.toggleAttribute('data-locked', st.noise === 0);
    }
  };

  useEffect(() => {
    const st = m.current;
    if (reduced) { st.f = DIAL.station; st.v = 0; st.mode = 'rest'; }
    st.shown = '';
    st.bars = -1;
    st.noise = -1;
    paint();
    const h = host.current;
    return () => { h?.style.removeProperty('--kt-noise'); h?.style.removeProperty('--kt-jit'); h?.removeAttribute('data-locked'); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  useRafLoop(wrap, (dt) => {
    const st = m.current;
    if (dt <= 0) return;
    if (st.delay > 0) { st.delay -= dt; return; }
    const step = (target: number, cfg: SpringConfig) => {
      const a = { x: st.f, v: st.v };
      stepSpring(a, target, cfg, dt);
      st.f = a.x; st.v = a.v;
    };
    if (st.mode === 'drag') step(st.target, spring.press);
    else if (st.mode === 'glide') {
      st.v *= Math.exp(-dt * 2.1);
      st.f += st.v * dt;
      // Past either end of the band the needle meets a soft stop and is pushed back.
      if (st.f < DIAL.min || st.f > DIAL.max) { st.v += (clampF(st.f) - st.f) * 220 * dt; st.v *= Math.exp(-dt * 10); }
      // The detent: passing the station slowly enough, it is caught and pulled in with a small overshoot.
      if (Math.abs(st.f - DIAL.station) < 0.6 && Math.abs(st.v) < 7) { st.mode = 'seek'; st.target = DIAL.station; st.cfg = spring.pop; }
      else if (Math.abs(st.v) < 0.04 && st.f >= DIAL.min && st.f <= DIAL.max) st.mode = 'rest';
    } else if (st.mode === 'seek') {
      step(st.target, st.cfg);
      if (Math.abs(st.f - st.target) < 0.002 && Math.abs(st.v) < 0.01) { st.f = st.target; st.v = 0; st.mode = 'rest'; }
    }
    // Static on the line while detuned: a jitter re-rolled about 20 times a second (frozen by Pause motion).
    const noise = 1 - signalAt(st.f);
    if (!paused && noise > 0.02) {
      st.jitT -= dt;
      if (st.jitT <= 0) { st.jitT = 0.05; host.current?.style.setProperty('--kt-jit', (Math.random() * 2 - 1).toFixed(2)); }
    } else if (noise <= 0.02) host.current?.style.setProperty('--kt-jit', '0');
    if (st.mode !== 'rest' || st.shown !== st.f.toFixed(1)) paint();
  }, !reduced);

  const fAt = (clientX: number): number => {
    const r = wrap.current?.getBoundingClientRect();
    if (!r) return m.current.f;
    const x = -12 + ((clientX - r.left) / Math.max(1, r.width)) * 1024;
    return DIAL.min + (x / 1000) * (DIAL.max - DIAL.min);
  };
  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    const st = m.current;
    const at = fAt(e.clientX);
    st.id = e.pointerId;
    // Grabbing the needle keeps the hand's offset; pressing elsewhere on the scale tunes toward that point.
    st.grab = Math.abs(at - st.f) < 0.9 ? st.f - at : 0;
    st.samples = [{ t: performance.now(), f: at + st.grab }];
    st.delay = 0;
    if (reduced) { st.f = clampF(at + st.grab); paint(); }
    else { st.mode = 'drag'; st.target = clampF(at + st.grab); }
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* gone */ }
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    const st = m.current;
    if (e.pointerId !== st.id) return;
    const raw = fAt(e.clientX) + st.grab;
    // Rubber band past the ends of the band.
    const t = raw < DIAL.min ? DIAL.min - (DIAL.min - raw) * 0.3 : raw > DIAL.max ? DIAL.max + (raw - DIAL.max) * 0.3 : raw;
    if (reduced) { st.f = clampF(t); paint(); return; }
    st.target = t;
    const now = performance.now();
    st.samples.push({ t: now, f: t });
    while (st.samples.length > 2 && now - st.samples[0].t > 100) st.samples.shift();
  };
  const onPointerEnd = (e: ReactPointerEvent<HTMLDivElement>) => {
    const st = m.current;
    if (e.pointerId !== st.id) return;
    st.id = -1;
    if (reduced) return;
    const a = st.samples[0];
    const b = st.samples[st.samples.length - 1];
    const throwV = a && b && b.t - a.t > 8 ? ((b.f - a.f) / (b.t - a.t)) * 1000 : 0;
    st.v = Math.max(-40, Math.min(40, (st.v + throwV) / 2));
    st.mode = 'glide';
  };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const st = m.current;
    const from = st.mode === 'seek' ? st.target : st.f;
    const keys: Record<string, number> = { ArrowRight: 0.1, ArrowUp: 0.1, ArrowLeft: -0.1, ArrowDown: -0.1, PageUp: 1, PageDown: -1 };
    let to: number | null = null;
    if (e.key in keys) to = Math.round((from + keys[e.key]) * 10) / 10;
    else if (e.key === 'Home') to = DIAL.min;
    else if (e.key === 'End') to = DIAL.max;
    if (to === null) return;
    e.preventDefault();
    to = clampF(to);
    // Stepping toward the station drops into its detent; stepping away never snaps back.
    if (Math.sign(DIAL.station - from) === Math.sign(to - from) && Math.abs(to - DIAL.station) < 0.25) to = DIAL.station;
    st.delay = 0;
    if (reduced) { st.f = to; st.v = 0; st.mode = 'rest'; paint(); return; }
    st.mode = 'seek';
    st.target = to;
    st.cfg = Math.abs(to - DIAL.station) < 0.05 ? spring.pop : spring.press;
  };

  return (
    <div
      ref={wrap}
      className={s.dialWrap}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerEnd}
      onPointerCancel={onPointerEnd}
    >
      <svg className={s.dial} viewBox="-12 0 1024 70" aria-hidden="true" focusable="false">
        <path className={s.dialRule} d="M0 40H1000" />
        {TICKS.map((f) => {
          const major = Number.isInteger(f) && f % 4 === 0;
          return <path key={f} className={major ? s.tickMajor : s.tick} d={`M${fx(f).toFixed(1)} ${major ? 22 : 30}V40`} />;
        })}
        {TICKS.filter((f) => Number.isInteger(f) && f % 4 === 0).map((f) => <text key={f} className={s.dialNum} x={fx(f)} y="60">{f}</text>)}
        <path className={s.stationMark} d={`M${fx(DIAL.station).toFixed(1)} 44V50`} />
        <g ref={shadow} className={s.needleShadow} transform={`translate(${fx(DIAL.from).toFixed(1)} 0)`}>
          <path d="M0 6V44" />
          <circle cy="6" r="5" />
        </g>
        <g ref={needle} className={s.needle} transform={`translate(${fx(DIAL.from).toFixed(1)} 0)`}>
          <path d="M0 6V44" />
          <circle cy="6" r="5" />
          <text ref={readout} className={s.readout} x="11" y="14">{DIAL.from.toFixed(1)}</text>
        </g>
        <g className={s.meter} transform="translate(930 4)">
          {[0, 1, 2, 3, 4].map((i) => <rect key={i} x={i * 9} y={14 - i * 3} width="5" height={6 + i * 3} rx="1" data-bar={i} />)}
        </g>
      </svg>
      <div
        ref={handle}
        className={s.dialHandle}
        role="slider"
        tabIndex={0}
        aria-label="Tuning"
        aria-valuemin={DIAL.min}
        aria-valuemax={DIAL.max}
        aria-valuenow={DIAL.from}
        aria-valuetext={`${DIAL.from.toFixed(1)} FM, static`}
        aria-orientation="horizontal"
        onKeyDown={onKeyDown}
      />
    </div>
  );
}

/*
 * Radio Haar — the night forecast as a broadcast transcript. Type is the only material: a timecode gutter,
 * mono for the broadcast data, Instrument Serif for the presenter's voice and Bricolage Grotesque with all
 * three axes for everything that moves. The display family must be loaded with its standard axes
 * (wght + wdth + opsz) — in the gallery, @fontsource-variable/bricolage-grotesque/standard.css.
 * One light: a desk lamp that follows the pointer (upper left at rest). Display type casts a contact and a soft
 * shadow away from it (--kt-sx/--kt-sy) with a rim on its lit side; the lamp's pool warms the paper under it.
 */
.root {
  --kt-pad: clamp(16px, 4cqi, 56px);
  --kt-axes: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
