  font-synthesis: none;
  --kt-sx: 0.56;
  --kt-sy: 0.76;
  --kt-rim: rgb(255 255 255 / 0.75);
  --kt-contact: rgb(17 17 15 / 0.2);
  --kt-soft: rgb(17 17 15 / 0.13);
  --kt-pool: rgb(255 250 238 / 0.95);
  --kt-vignette: rgb(17 17 15 / 0.07);
}
