  --kt-soft: rgb(0 0 0 / 0.55);
  --kt-pool: rgb(255 176 104 / 0.13);
  --kt-vignette: rgb(0 0 0 / 0.25);
}

/* The lamp's pool of light: a viewport-sized sticky layer whose gradient centre follows the lamp (repainted only while
   the lamp moves). Beyond the pool the vignette's last stop simply continues, so there is no edge anywhere. */
.lampPool {
  position: sticky;
  top: 0;
  z-index: 0;
  height: 100svh;
  margin-bottom: -100svh;
