  text-shadow:
    calc(var(--kt-sx) * -0.012em) calc(var(--kt-sy) * -0.012em) 0 var(--kt-rim),
    calc(var(--kt-sx) * 0.022em) calc(var(--kt-sy) * 0.022em) 0 var(--kt-contact),
